function optionsForMetric(metric,type){
 const custom=responseOptions.filter(x=>x.metric_id===metric.id&&x.kind===type&&x.active!==false).map(x=>({id:x.id,text:x.response}));
 const index={strengths:0,improvements:1,drills:2}[type];
 const fallback=(SKILL_RESPONSES[skillKey(metric)]||SKILL_RESPONSES.attitude)[index].map((text,i)=>({id:'default-'+i,text}));
 const extras=(BASEBALL_RESPONSE_EXTRAS[skillKey(metric)]?.[type]||EXTRA_RESPONSES[type]).map((text,i)=>({id:'extra-'+i,text}));
 const combined=[...fallback,...extras,...custom];
 const unique=[];const seen=new Set();
 for(const item of combined){if(!seen.has(item.text)){seen.add(item.text);unique.push(item)}}
 return unique;
}
function getSelections(){
 const out={};
 document.querySelectorAll('[data-observation]').forEach(el=>{
  const key=el.dataset.observation,kind=el.dataset.kind;
  out[key]??={};
  const chosen=[...el.querySelectorAll('input[type="checkbox"]:checked')].map(i=>i.value);
  const custom=el.querySelector('[data-custom-response]')?.value.trim();
  if(custom)chosen.push(custom);
  out[key][kind]=chosen;
 });
 document.querySelectorAll('[data-custom-note]').forEach(el=>{
  out[el.dataset.customNote]??={};out[el.dataset.customNote].note=el.value;
 });
 return out;
}
function renderMetricInputs(){
 const level=Number($('evalLevel').value||2);
 $('levelInfo').textContent=['','Foundation: broad essentials','Development: skill fundamentals','Advanced: detailed skills and observations','Comprehensive: all criteria'][level];
 const selected=metrics.filter(m=>m.active);
 $('metricInputs').innerHTML=CATEGORY_ORDER.map(category=>{
  const subset=selected.filter(m=>m.category===category).slice(0,level===1?2:level===2?4:Infinity);
  if(!subset.length)return '';
  return `<h3>${category}</h3>`+subset.map(m=>`<div class="card" data-metric-card="${m.id}">
   <div class="metric"><div><b>${escapeHtml(m.name)}</b><div class="muted"><small>${escapeHtml(m.description)}</small></div></div>
   <select data-score="${m.id}" aria-label="Score ${escapeHtml(m.name)}"><option value="">Not Rated</option>${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}">${n} / 8</option>`).join('')}</select></div>
   ${['strengths','improvements','drills'].map(kind=>{
    const label={strengths:'Strengths',improvements:'Areas for Improvement',drills:'Recommended Drills'}[kind];
    return `<details class="response-picker" data-observation="${m.id}" data-kind="${kind}"><summary>${label} — <span class="response-count">Choose responses</span></summary><div class="response-picker-body">${optionsForMetric(m,kind).map(o=>`<label class="response-choice"><input type="checkbox" value="${escapeHtml(o.text)}"> <span>${escapeHtml(o.text)}</span></label>`).join('')}<label class="custom-response-label">Custom response (optional)</label><textarea data-custom-response rows="2" placeholder="Type a specific observation or drill for this player..."></textarea></div></details>`;
   }).join('')}
   <label>Coach-specific notes</label><textarea data-custom-note="${m.id}" placeholder="Optional observation for this player"></textarea>
  </div>`).join('');
 }).join('');
}
function updateResponseCount(picker){
 const count=picker.querySelectorAll('input:checked').length+(picker.querySelector('[data-custom-response]')?.value.trim()?1:0);
 picker.querySelector('.response-count').textContent=count?`${count} selected`:'Choose responses';
}
function renderResponseLibrary(){const el=$('responseMetric');if(!el)return;const old=el.value;el.innerHTML=metrics.map(m=>`<option value="${m.id}">${escapeHtml(m.category+' — '+m.name)}</option>`).join('');if(metrics.some(m=>m.id===old))el.value=old;const m=metrics.find(x=>x.id===el.value);if(!m)return;const kind=$('responseType').value;$('responseRows').innerHTML=optionsForMetric(m,kind).map(o=>`<div class="metric"><span>${escapeHtml(o.text)}</span>${isAdmin&&o.id&&!o.id.startsWith('default-')?`<button data-remove-response="${o.id}">Remove</button>`:''}</div>`).join('');$('addResponse').disabled=!isAdmin;$('responseText').disabled=!isAdmin;$('adminInfo').textContent=isAdmin?'Administrator: changes update the shared response library.':'Standard responses are view-only. Ask your administrator to manage shared defaults.'}
async function loadResponseOptions(){const r=await db.from('pd_response_options').select('*').eq('org',org);if(r.error)throw Error('V7 database migration required. Run migration-v7.sql in Supabase first: '+r.error.message);responseOptions=r.data||[];const a=await db.from('pd_eval_admins').select('email').eq('org',org).eq('email',session.user.email.toLowerCase()).maybeSingle();if(a.error)throw a.error;isAdmin=!!a.data}
function renderLibrary(){$('libraryRows').innerHTML=['Offense','Defense','Character'].map(c=>`<h3>${c}</h3>`+metrics.filter(m=>m.category===c).map(m=>`<div class="metric"><div><b>${escapeHtml(m.name)}</b><div class="muted">${escapeHtml(m.description)}</div></div><label style="white-space:nowrap;color:white"><input type="checkbox" data-toggle="${m.id}" ${m.active?'checked':''} style="width:auto"> Include</label></div>`).join('')).join('')}
function observationSummary(e){return Object.entries(e.observations||{}).map(([id,o])=>{const m=metrics.find(x=>x.id===id);return `<div class="card"><b>${escapeHtml(m?.name||'Skill')}</b>${['strengths','improvements','drills'].map(k=>(o[k]||[]).length?`<p><b>${{strengths:'Strengths',improvements:'Areas for Improvement',drills:'Recommended Drills'}[k]}:</b> ${o[k].map(escapeHtml).join('; ')}</p>`:'').join('')}${o.note?`<p><b>Coach Notes:</b> ${escapeHtml(o.note)}</p>`:''}</div>`}).join('')}
function scoreMap(e){return e.scores||{}}
function average(e,category){const vals=Object.entries(scoreMap(e)).filter(([id,n])=>{const m=metrics.find(m=>m.id===id);return m?.category===category&&Number(n)>0}).map(([,n])=>Number(n));return vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1):'—'}
function renderProgress(){const id=$('progressPlayer').value, target=$('progressReport');if(!id){target.innerHTML='<p class="muted">Select a player to see scores and progress.</p>';return}const p=players.find(p=>p.id===id),items=evaluations.filter(e=>e.player_id===id).sort((a,b)=>a.evaluated_at.localeCompare(b.evaluated_at));if(!items.length){target.innerHTML='<p>No evaluations saved for this player yet.</p>';return}const first=items[0],last=items[items.length-1];let rows=metrics.filter(m=>items.some(e=>scoreMap(e)[m.id]!=null)).map(m=>{const a=scoreMap(first)[m.id],b=scoreMap(last)[m.id],delta=a!=null&&b!=null?Number(b)-Number(a):null;return `<tr><td>${escapeHtml(m.category)} / ${escapeHtml(m.name)}</td><td>${a??'—'}</td><td>${b??'—'}</td><td>${delta===null?'—':(delta>0?'+':'')+delta}</td></tr>`}).join('');target.innerHTML=`<h3>${escapeHtml(fullName(p))} — ${escapeHtml(p.team)}</h3><p>${items.length} evaluation(s) · ${escapeHtml(first.evaluated_at)} to ${escapeHtml(last.evaluated_at)}</p><div class="grid triple">${['Offense','Defense','Character'].map(c=>`<div class="card"><b>${c}</b><div class="score">${average(last,c)}</div><small>Latest average / 8</small></div>`).join('')}</div><h3>First vs. Most Recent</h3><div class="scroll"><table><thead><tr><th>Criterion</th><th>First</th><th>Latest</th><th>Change</th></tr></thead><tbody>${rows}</tbody></table></div><h3>Evaluation Timeline</h3><div class="scroll"><table><thead><tr><th>Date</th><th>Setting</th><th>Offense</th><th>Defense</th><th>Character</th><th>Coach</th></tr></thead><tbody>${items.map(e=>`<tr><td>${escapeHtml(e.evaluated_at)}</td><td>${escapeHtml(e.setting)}</td><td>${average(e,'Offense')}</td><td>${average(e,'Defense')}</td><td>${average(e,'Character')}</td><td>${escapeHtml(e.coach_email)}</td></tr>`).join('')}</tbody></table></div><h3>Latest Coach Feedback</h3><p><b>Strengths:</b> ${escapeHtml(last.strengths)}</p><p><b>Areas to improve:</b> ${escapeHtml(last.weaknesses)}</p><p><b>Notes:</b> ${escapeHtml(last.notes)}</p><h3>Selected Coaching Observations</h3>${observationSummary(last)}<h3>Score Trend</h3>${['Offense','Defense','Character'].map(c=>`<div style="margin:10px 0"><b>${c}</b>${items.map(e=>{const n=Number(average(e,c));return `<div class="flex" style="margin:5px 0"><small style="width:95px">${escapeHtml(e.evaluated_at)}</small><div class="bar" style="flex:1"><span style="width:${Number.isFinite(n)?n*12.5:0}%"></span></div><small style="width:35px">${Number.isFinite(n)?n.toFixed(1):'—'}</small></div>`}).join('')}</div>`).join('')}`}

function playerEvaluations(id){return evaluations.filter(e=>e.player_id===id).sort((a,b)=>a.evaluated_at.localeCompare(b.evaluated_at)||a.created_at.localeCompare(b.created_at))}
function scoreDelta(n,old){if(old==null)return 'New';const d=Number(n)-Number(old);return d>0?'↑ +'+d:d<0?'↓ '+d:'→ 0'}
function renderPrevious(){const id=$('evalPlayer').value, target=$('previousEvaluation');if(!id){target.innerHTML='<p class="muted">Choose a player to see their previous evaluation and score trends.</p>';return}const history=playerEvaluations(id).filter(e=>e.id!==$('editingEvaluationId').value),last=history.at(-1);if(!last){target.innerHTML='<p class="muted">First evaluation for this player — no previous scores.</p>';return}target.innerHTML='<h3>Previous Evaluation: '+escapeHtml(last.evaluated_at)+'</h3><p class="muted">Changes compare your current scores with the latest saved evaluation.</p><div id="previousScoreRows"></div>';renderScoreComparison()}
function renderScoreComparison(){const id=$('evalPlayer').value,last=playerEvaluations(id).filter(e=>e.id!==$('editingEvaluationId').value).at(-1),target=$('previousScoreRows');if(!target||!last)return;target.innerHTML=[...document.querySelectorAll('[data-score]')].map(s=>{const m=metrics.find(m=>m.id===s.dataset.score),prev=last.scores?.[s.dataset.score],now=s.value;return `<div class="metric"><span>${escapeHtml(m?.name||'Skill')}</span><span>Previous: ${prev??'—'} · Current: ${now||'—'} ${now?scoreDelta(now,prev):''}</span></div>`}).join('')}
function renderSavedEvaluations(){const id=$('progressPlayer').value,target=$('savedEvaluationList');if(!id){target.innerHTML='<p class="muted">Select a player to access saved evaluations.</p>';return}const history=playerEvaluations(id).slice().reverse();target.innerHTML=history.length?history.map(e=>`<div class="metric"><div><b>${escapeHtml(e.evaluated_at)} — ${escapeHtml(e.setting)}</b><div class="muted"><small>Offense ${average(e,'Offense')} · Defense ${average(e,'Defense')} · Character ${average(e,'Character')} · ${escapeHtml(e.coach_email)}</small></div></div><div class="eval-actions noprint"><button data-edit-eval="${e.id}">Open / Edit</button><button class="danger-button" data-delete-eval="${e.id}">Delete</button></div></div>`).join(''):'<p>No evaluations saved for this player.</p>'}
async function deleteSavedEvaluation(id){
 const record=evaluations.find(x=>x.id===id);
 if(!record){error(Error('Evaluation not found. Refresh and try again.'));return}
 const player=players.find(x=>x.id===record.player_id);
 const name=player?[player.first_name,player.last_name].filter(Boolean).join(' '):'this player';
 if(!window.confirm(`Permanently delete the ${record.evaluated_at} ${record.setting||''} evaluation for ${name}? This cannot be undone. Saved improvement plans will remain, but evaluation trends will be recalculated.`))return;
 try{
  const result=await db.from('pd_evaluations').delete().eq('id',id).eq('org',org).select('id');
  check(result);
  if(!result.data?.length)throw Error('No evaluation was deleted. Check database permissions.');
  if($('editingEvaluationId').value===id)resetEvaluation();
  await loadAll();
  $('progressPlayer').value=record.player_id;
  renderProgress();renderSavedEvaluations();
  message('Evaluation deleted. Progress trends updated. Existing improvement plans were kept.');
 }catch(e){error(e)}
}
function startEditEvaluation(id){const e=evaluations.find(x=>x.id===id);if(!e)return;$('editingEvaluationId').value=e.id;$('evalPlayer').value=e.player_id;$('evalDate').value=e.evaluated_at;$('evalSetting').value=e.setting;$('evalLevel').value=e.level||2;renderMetricInputs();Object.entries(e.observations||{}).forEach(([metricId,entry])=>{for(const kind of ['strengths','improvements','drills']){const picker=document.querySelector(`[data-observation="${metricId}"][data-kind="${kind}"]`);if(picker){const saved=entry[kind]||[];const known=new Set([...picker.querySelectorAll('input[type="checkbox"]')].map(o=>o.value));picker.querySelectorAll('input[type="checkbox"]').forEach(o=>o.checked=saved.includes(o.value));const custom=picker.querySelector('[data-custom-response]');if(custom)custom.value=saved.filter(x=>!known.has(x)).join('; ');updateResponseCount(picker)}}const note=document.querySelector(`[data-custom-note="${metricId}"]`);if(note)note.value=entry.note||''});$('strengths').value=e.strengths||'';$('weaknesses').value=e.weaknesses||'';$('coachNotes').value=e.notes||'';document.querySelectorAll('[data-score]').forEach(s=>s.value=e.scores?.[s.dataset.score]??'');$('evaluationHeading').textContent='Edit Saved Evaluation';$('saveEvaluation').textContent='Update Evaluation';$('cancelEvaluationEdit').classList.remove('hide');setTab('evaluation');renderPrevious();window.scrollTo({top:0,behavior:'smooth'})}
function resetEvaluation(){ $('editingEvaluationId').value='';$('evaluationHeading').textContent='Player Evaluation';$('saveEvaluation').textContent='Save Evaluation';$('cancelEvaluationEdit').classList.add('hide');['strengths','weaknesses','coachNotes'].forEach(id=>$(id).value='');document.querySelectorAll('[data-score]').forEach(s=>s.value='');renderPrevious()}

const PLAN_TEMPLATES={
 Offense:['Review the hitting fundamentals and identify the specific movement or decision to improve.','Complete 3 tee-work sessions per week: 3 sets of 10 purposeful swings with coach feedback.','Progress to front toss and soft toss with 3 sets of 10 quality repetitions, focusing on the same skill.','Apply the movement in controlled machine or live batting practice once fundamentals are consistent.','Reevaluate in 14 days using the same scouting criterion and record video or observable results.'],
 Defense:['Review ready position, footwork, glove presentation, throwing mechanics and situational responsibilities.','Complete 3 focused fielding sessions weekly, 15–20 controlled repetitions per session.','Progress to moving balls, throws on the run and situational defensive decisions.','Apply the skill in game-speed repetitions and document execution and decision quality.','Reevaluate in 14 days with the same defensive criterion and compare to the prior score.'],
 Character:['Discuss the specific behavior and establish one clear, observable standard for practice and games.','Practice the standard at every team activity with a short pre-practice reminder.','Use real situations to demonstrate effort, coachability, communication and teammate support.','Coach gives specific weekly feedback and records examples of progress.','Reevaluate in 14 days using observed behavior rather than a single incident.']
};
let planSteps=[];
function escapeAttr(v){return escapeHtml(String(v??'')).replace(/"/g,'&quot;')}
function defaultSteps(){const metric=metrics.find(m=>m.id===$('planMetric').value);const cat=metric?.category||'Defense';return (PLAN_TEMPLATES[cat]||PLAN_TEMPLATES.Defense).map((description,i)=>({title:['Fundamentals','Controlled Repetitions','Game-Speed Application','Coach Feedback','Reevaluation'][i],description}))}
function renderPlanSteps(){$('planSteps').innerHTML=planSteps.map((s,i)=>`<div class="card" data-step-index="${i}"><div class="flex"><b>Step ${i+1}</b><button type="button" data-remove-step="${i}">Remove</button></div><label>Step name</label><input data-step-title="${i}" value="${escapeAttr(s.title)}"><label>Instructions / Drills</label><textarea data-step-description="${i}">${escapeHtml(s.description)}</textarea><div class="flex"><button type="button" data-move-step="${i}" data-direction="-1" ${i===0?'disabled':''}>Move Up</button><button type="button" data-move-step="${i}" data-direction="1" ${i===planSteps.length-1?'disabled':''}>Move Down</button></div></div>`).join('')}
function setDefaultSteps(){planSteps=defaultSteps();renderPlanSteps()}
function stepsToText(){return planSteps.map((s,i)=>`${i+1}. ${s.title}\n${s.description}`).join('\n\n')}
function parseSavedSteps(actions){const txt=String(actions||'');const matches=[...txt.matchAll(/(?:^|\n\n)(\d+)\.\s+([^\n]+)\n([\s\S]*?)(?=\n\n\d+\.\s+|$)/g)];return matches.length?matches.map(m=>({title:m[2],description:m[3].trim()})):txt?[{title:'Practice Actions',description:txt}]:defaultSteps()}
$('planSteps').addEventListener('input',e=>{const i=Number(e.target.dataset.stepTitle??e.target.dataset.stepDescription);if(!Number.isInteger(i)||!planSteps[i])return;if(e.target.hasAttribute('data-step-title'))planSteps[i].title=e.target.value;if(e.target.hasAttribute('data-step-description'))planSteps[i].description=e.target.value});
$('planSteps').addEventListener('click',e=>{const rm=e.target.closest('[data-remove-step]');if(rm){planSteps.splice(Number(rm.dataset.removeStep),1);renderPlanSteps();return}const mv=e.target.closest('[data-move-step]');if(mv){const i=Number(mv.dataset.moveStep),j=i+Number(mv.dataset.direction);if(j<0||j>=planSteps.length)return;[planSteps[i],planSteps[j]]=[planSteps[j],planSteps[i]];renderPlanSteps()}});
$('addPlanStep').onclick=()=>{planSteps.push({title:'New Step',description:''});renderPlanSteps()};
$('resetPlanSteps').onclick=setDefaultSteps;
$('planMetric').addEventListener('change',()=>{if(!$('editingPlanId').value)makePlanDraft()});
function makePlanDraft(){const id=$('planPlayer').value;if(!id)return;const history=playerEvaluations(id),last=history.at(-1);if(!last){$('planAutoNote').textContent='No saved evaluations yet. Default steps are available for a manual plan.';setDefaultSteps();return}const scored=Object.entries(last.scores||{}).map(([id,v])=>({metric:metrics.find(m=>m.id===id),value:Number(v)})).filter(x=>x.metric&&x.value>=1&&x.value<=8).sort((a,b)=>a.value-b.value);if(!scored.length)return;const focus=scored[0],prior=history.slice(0,-1).reverse().find(e=>e.scores?.[focus.metric.id]!=null),priorScore=prior?.scores?.[focus.metric.id],goalScore=Math.min(8,focus.value+1);$('planMetric').value=focus.metric.id;setDefaultSteps();$('planGoal').value=`Improve ${focus.metric.name} from ${focus.value}/8 to ${goalScore}/8 by the next review.`;const selectedDrills=last.observations?.[focus.metric.id]?.drills||[];if(selectedDrills.length){planSteps[1].description=selectedDrills.join(' ');renderPlanSteps()}$('planActions').value=stepsToText();$('planMeasure').value=`Coach reevaluation score reaches ${goalScore}/8, supported by consistent performance in practices and games.`;$('planAutoNote').textContent=`Suggested from ${last.evaluated_at} evaluation. ${focus.metric.name}: ${focus.value}/8${priorScore!=null?` (previously ${priorScore}/8, ${scoreDelta(focus.value,priorScore)})`:''}. Review and edit the draft before saving.`}
function startEditPlan(id){const p=plans.find(x=>x.id===id);if(!p)return;$('editingPlanId').value=id;$('planPlayer').value=p.player_id;$('planMetric').value=p.metric_id||'';$('targetDate').value=p.target_date||'';$('planGoal').value=p.goal||'';$('planActions').value=p.actions||'';$('planMeasure').value=p.measure||'';planSteps=parseSavedSteps(p.actions);renderPlanSteps();$('planHeading').textContent='Edit Saved Improvement Plan';$('savePlan').textContent='Update Plan';$('cancelPlanEdit').classList.remove('hide');$('planAutoNote').textContent='Editing an existing plan. Save changes to update it.';setTab('plans');window.scrollTo({top:0,behavior:'smooth'})}
function resetPlan(){planSteps=[];renderPlanSteps();$('editingPlanId').value='';$('planHeading').textContent='Improvement Plan';$('savePlan').textContent='Save Plan';$('cancelPlanEdit').classList.add('hide');['planGoal','planActions','planMeasure','targetDate'].forEach(id=>$(id).value='');$('planAutoNote').textContent='Select a player to generate a suggested improvement plan from saved evaluations.'}
function renderPlans(){$('planList').innerHTML=plans.length?plans.map(p=>{const player=players.find(x=>x.id===p.player_id),metric=metrics.find(x=>x.id===p.metric_id);return `<div class="card"><div class="flex"><h3 style="flex:1">${escapeHtml(player?fullName(player):'Unknown Player')} — ${escapeHtml(metric?.name||'Focus')}</h3><span class="pill">${escapeHtml(p.status)}</span></div><p><b>Goal:</b> ${escapeHtml(p.goal)}</p><p><b>Practice Actions:</b> ${escapeHtml(p.actions)}</p><p><b>Success Measure:</b> ${escapeHtml(p.measure)}</p><p><b>Review Date:</b> ${escapeHtml(p.target_date)}</p><div class="noprint"><button data-print-plan="${p.id}">Print / Save PDF</button> <button data-edit-plan="${p.id}">Edit Plan</button> <button data-complete="${p.id}">${p.status==='Complete'?'Reopen Plan':'Mark Complete'}</button> <button class="danger-button" data-delete-plan="${p.id}">Delete Plan</button></div></div>`}).join(''):'<p class="muted">No improvement plans yet.</p>'}
async function addPlayer(first,last,team,jersey){first=cleanName(first);last=cleanName(last);team=String(team??'').trim();if(!first||!last||!team)throw Error('First name, last name and team are required.');if(players.some(p=>p.first_name.toLowerCase()===first.toLowerCase()&&p.last_name.toLowerCase()===last.toLowerCase()&&p.team.toLowerCase()===team.toLowerCase()))return false;check(await db.from('pd_players').insert({org,first_name:first,last_name:last,team,jersey:jersey||null}));return true}
function csvRows(raw){const result=[];let row=[],cell='',quoted=false;for(let i=0;i<raw.length;i++){const ch=raw[i];if(ch==='"'){if(quoted&&raw[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&raw[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))result.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(v=>v.trim()))result.push(row);return result}
function download(name,body){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('connect').onclick=connect;$('changeDb').onclick=()=>{localStorage.removeItem('playerdev_config');location.reload()};$('login').onclick=async()=>{try{check(await db.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value}));await restore()}catch(e){error(e)}};$('logout').onclick=async()=>{await db.auth.signOut();session=null;$('logout').classList.add('hide');visible('authPanel')};$('joinOrg').onclick=async()=>{try{org=$('orgCode').value.trim().toLowerCase();if(!/^[a-z0-9][a-z0-9-]{2,60}$/.test(org))throw Error('Use 3–61 lowercase letters, numbers or hyphens.');localStorage.setItem('playerdev_org',org);await loadAll();visible('app')}catch(e){error(e)}};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
$('addPlayer').onclick=async()=>{try{await addPlayer($('first').value,$('last').value,$('team').value,$('jersey').value);['first','last','jersey'].forEach(id=>$(id).value='');await loadAll();message('Player added')}catch(e){error(e)}};
$('rosterRows').onclick=e=>{const btn=e.target.closest('[data-edit-player]');if(!btn)return;const p=players.find(x=>x.id===btn.dataset.editPlayer);if(!p)return;$('editPlayerId').value=p.id;$('editFirst').value=cleanName(p.first_name);$('editLast').value=cleanName(p.last_name);$('editTeam').value=p.team;$('editJersey').value=p.jersey||'';$('editPlayerPanel').classList.remove('hide');$('editPlayerPanel').scrollIntoView({behavior:'smooth',block:'center'})};
$('cancelPlayerEdit').onclick=()=>{$('editPlayerPanel').classList.add('hide')};
$('savePlayerEdit').onclick=async()=>{try{const id=$('editPlayerId').value;const first_name=cleanName($('editFirst').value),last_name=cleanName($('editLast').value),team=$('editTeam').value.trim(),jersey=$('editJersey').value.trim();if(!id||!first_name||!last_name||!team)throw Error('First name, last name and team are required.');if(players.some(p=>p.id!==id&&cleanName(p.first_name).toLowerCase()===first_name.toLowerCase()&&cleanName(p.last_name).toLowerCase()===last_name.toLowerCase()&&p.team.toLowerCase()===team.toLowerCase()))throw Error('A player with this name already exists on that team.');check(await db.from('pd_players').update({first_name,last_name,team,jersey:jersey||null}).eq('id',id).eq('org',org));$('editPlayerPanel').classList.add('hide');await loadAll();message('Player updated. Existing evaluations preserved.')}catch(e){error(e)}};
$('template').onclick=()=>download('player_roster_template.csv','First Name,Last Name,Team,Jersey Number\r\nJane,Doe,14U A,12\r\n');
$('csv').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;const bytes=await file.arrayBuffer();let raw=new TextDecoder('utf-8').decode(bytes);if(raw.includes('\uFFFD'))raw=new TextDecoder('windows-1252').decode(bytes);const rows=csvRows(raw.replace(/^\uFEFF/,'')),headers=rows.shift().map(s=>s.trim().toLowerCase().replace(/[^a-z]/g,''));const idx=(...names)=>headers.findIndex(h=>names.includes(h));const first=idx('firstname','first'),last=idx('lastname','last'),name=idx('name','playername'),team=idx('team','agegroup','division'),jersey=idx('jerseynumber','jersey','number');if(team<0||(name<0&&(first<0||last<0)))throw Error('CSV needs Team and Name or First Name / Last Name columns.');let added=0,skipped=0;for(const r of rows){const full=name>=0?(r[name]||'').trim().split(/\s+/):[];const f=cleanName(first>=0?r[first]:full[0]),l=cleanName(last>=0?r[last]:full.slice(1).join(' '));if(!f||!l||!r[team]){skipped++;continue}if(await addPlayer(f,l,r[team],jersey>=0?r[jersey]:'') )added++;else skipped++}await loadAll();$('importInfo').textContent=`Imported ${added} players; skipped ${skipped} duplicates/incomplete rows.`;message('Roster import finished')}catch(e){error(e)}finally{ev.target.value=''}};

