$('savePlan').onclick=async()=>{try{if(!$('planPlayer').value||!$('planMetric').value||!$('planGoal').value.trim())throw Error('Choose a player, skill and goal.');const payload={org,player_id:$('planPlayer').value,metric_id:$('planMetric').value,target_date:$('targetDate').value||null,goal:$('planGoal').value,actions:stepsToText()||$('planActions').value,measure:$('planMeasure').value,coach_email:session.user.email};const editId=$('editingPlanId').value;if(editId){check(await db.from('pd_plans').update(payload).eq('id',editId).eq('org',org))}else{check(await db.from('pd_plans').insert({...payload,status:'Active'}))}resetPlan();await loadAll();message(editId?'Improvement plan updated':'Improvement plan saved for future access')}catch(e){error(e)}};

function printSavedPlan(id){
 const p=plans.find(x=>x.id===id);if(!p){message('Plan not found');return}
 const player=players.find(x=>x.id===p.player_id),metric=metrics.find(x=>x.id===p.metric_id);
 const steps=parseSavedSteps(p.actions);
 const stepMarkup=steps.map((s,i)=>`<div class="print-step"><strong>Step ${i+1}: ${escapeHtml(s.title)}</strong><p>${escapeHtml(s.description)}</p></div>`).join('');
 $('planPrintSheet').innerHTML=`<h1>PLAYER EVALUATION — IMPROVEMENT PLAN</h1><div class="print-meta"><div><strong>Player:</strong> ${escapeHtml(player?fullName(player):'Unknown Player')}</div><div><strong>Team:</strong> ${escapeHtml(player?.team||'—')}</div></div><div class="print-meta"><div><strong>Focus Skill:</strong> ${escapeHtml(metric?.name||'—')}</div><div><strong>Review Date:</strong> ${escapeHtml(p.target_date||'Not set')}</div><div><strong>Status:</strong> ${escapeHtml(p.status||'Active')}</div></div><h2>Measurable Goal</h2><p>${escapeHtml(p.goal||'—')}</p><h2>Development Steps</h2>${stepMarkup}<h2>Success Measure</h2><p>${escapeHtml(p.measure||'—')}</p><div class="print-signatures"><span>Coach Signature / Date</span><span>Player / Parent Acknowledgment</span></div>`;
 document.body.classList.add('printing-plan');
 const cleanup=()=>{document.body.classList.remove('printing-plan');window.removeEventListener('afterprint',cleanup)};
 window.addEventListener('afterprint',cleanup);
 window.print();
}
async function deleteIndividualPlan(id){
 const plan=plans.find(p=>p.id===id);
 if(!plan){error(Error('Plan not found. Refresh and try again.'));return}
 const player=players.find(p=>p.id===plan.player_id);
 const metric=metrics.find(m=>m.id===plan.metric_id);
 const label=`${player?fullName(player):'Unknown Player'} — ${metric?.name||'Improvement Plan'}`;
 if(!window.confirm(`Permanently delete this improvement plan?\n\n${label}\n\nThis cannot be undone. The player's evaluations and other plans will not be deleted.`))return;
 try{
  const result=await db.from('pd_plans').delete().eq('id',id).eq('org',org).select('id');
  check(result);
  if(!result.data?.length)throw Error('The plan was not deleted. Check database permissions.');
  if(typeof editingPlanId!=='undefined' && editingPlanId===id){editingPlanId=null;}
  await loadAll();
  message('Improvement plan deleted. Other plans and evaluations were preserved.');
 }catch(err){error(err)}
}
$('planList').onclick=async e=>{const del=e.target.closest('[data-delete-plan]');if(del){await deleteIndividualPlan(del.dataset.deletePlan);return}const print=e.target.closest('[data-print-plan]');if(print){printSavedPlan(print.dataset.printPlan);return}const edit=e.target.closest('[data-edit-plan]');if(edit){startEditPlan(edit.dataset.editPlan);return}const btn=e.target.closest('[data-complete]');if(!btn)return;try{const p=plans.find(p=>p.id===btn.dataset.complete);check(await db.from('pd_plans').update({status:p.status==='Complete'?'Active':'Complete'}).eq('id',p.id).eq('org',org));await loadAll()}catch(e){error(e)}};
$('addMetric').onclick=async()=>{try{const name=$('metricName').value.trim();if(!name)throw Error('Enter a criterion name.');check(await db.from('pd_metrics').insert({org,category:$('metricCategory').value,name,description:$('metricDesc').value.trim(),active:true}));$('metricName').value='';$('metricDesc').value='';await loadAll();message('Criterion added')}catch(e){error(e)}};
$('libraryRows').onchange=async e=>{const id=e.target.dataset.toggle;if(!id)return;try{check(await db.from('pd_metrics').update({active:e.target.checked}).eq('id',id).eq('org',org));await loadAll()}catch(err){error(err)}};
$('evalDate').value=new Date().toLocaleDateString('en-CA');
async function bootDatabase(){
 try {
   const r=await fetch('/api/public-config',{cache:'no-store'});
   if(r.ok){const cfg=await r.json();if(cfg.configured){initDb(cfg.url,cfg.key);await restore();return}}
   // Keep working for the existing administrator if a previous browser connection is available.
   const saved=localStorage.getItem('playerdev_config');
   if(saved){const cfg=JSON.parse(saved);if(cfg.url&&cfg.key){initDb(cfg.url,cfg.key);await restore();return}}
   visible('configPanel');
   $('configHelp').textContent='Automatic connection is not configured in Vercel yet. The administrator must set SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY once in Vercel Environment Variables, then redeploy. Coaches will not need to enter these.';
 }catch(e){error(e);visible('configPanel');$('configHelp').textContent='Automatic connection failed. Check the Vercel environment variables and deployment.'}
}
bootDatabase();


$('evalLevel').onchange=()=>{renderMetricInputs();renderPrevious()};
$('responseMetric').onchange=renderResponseLibrary;
$('responseType').onchange=renderResponseLibrary;
$('addResponse').onclick=async()=>{try{if(!isAdmin)throw Error('Administrator access required');const response=$('responseText').value.trim();if(!response)throw Error('Enter a response');check(await db.from('pd_response_options').insert({org,metric_id:$('responseMetric').value,kind:$('responseType').value,response,active:true}));$('responseText').value='';await loadResponseOptions();renderResponseLibrary();renderMetricInputs();message('Shared response added')}catch(e){error(e)}};
$('responseRows').onclick=async e=>{const b=e.target.closest('[data-remove-response]');if(!b)return;try{if(!isAdmin)throw Error('Administrator access required');check(await db.from('pd_response_options').update({active:false}).eq('id',b.dataset.removeResponse).eq('org',org));await loadResponseOptions();renderResponseLibrary();renderMetricInputs();message('Response disabled')}catch(e){error(e)}};

